import sys

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    capacity = int(lines[0].strip())
    arr = [None] * capacity
    head = 0
    tail = 0
    count = 0

    def display():
        res = []
        for i in range(count):
            res.append(str(arr[(head + i) % capacity]))
        print(" ".join(res))

    for line in lines[1:]:
        line = line.strip()
        if line == "exit":
            break
        parts = line.split()
        cmd = parts[0]
        if cmd == "insertFront":
            x = int(parts[1])
            if count < capacity:
                head = (head - 1) % capacity
                arr[head] = x
                count += 1
        elif cmd == "insertRear":
            x = int(parts[1])
            if count < capacity:
                arr[tail] = x
                tail = (tail + 1) % capacity
                count += 1
        elif cmd == "deleteFront":
            if count > 0:
                head = (head + 1) % capacity
                count -= 1
        elif cmd == "deleteRear":
            if count > 0:
                tail = (tail - 1) % capacity
                count -= 1
        elif cmd == "display":
            display()

if __name__ == "__main__":
    main()
